// Spec 608 · someone comes home, an original illustration. A tall grey heron walks slowly up the river path, stopping
// once to look at the brook, and comes to rest beside the flood post with its newest mark, *Warned in time*. Everything
// settles within a few seconds; reduced motion shows the heron already at the post.
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const heron='<g class="a6h-heron"><path d="M0 -6 C 14 -16 34 -12 40 -2 C 30 6 10 8 0 -6Z" fill="#9aa3a8"/><path d="M8 -10 C 4 -30 6 -48 14 -58" stroke="#9aa3a8" stroke-width="5" fill="none" stroke-linecap="round"/><circle cx="16" cy="-60" r="6" fill="#aab3b8"/><path d="M21 -60 l18 3 l-18 2z" fill="#d9a441"/><circle cx="18" cy="-61" r="1.4" fill="#222"/><path d="M14 -64 q-10 -4 -16 2" stroke="#3a3a3a" stroke-width="2" fill="none"/><path d="M16 4 v34 M24 4 v34" stroke="#c9a46a" stroke-width="2.5"/></g>';
export function heronScene(label,caption,{settled=false}={}){
 return `<figure class="a6h-home${settled?' a6h-settled':''}" data-a6h-home><svg viewBox="0 0 640 300" role="img" aria-label="${esc(label)}"><rect width="640" height="300" fill="#e9ede6"/><path d="M0 230 Q160 214 320 226 T640 222 V300 H0Z" fill="#8fb4cc"/><path d="M0 214 C 160 196 360 206 640 186" stroke="#c9b48e" stroke-width="16" fill="none"/><rect x="470" y="96" width="14" height="124" fill="#8a6a4a"/>${[200,176,152,128].map(y=>`<path d="M484 ${y} h18" stroke="#4a4036" stroke-width="3"/>`).join('')}<path d="M482 164 h26" stroke="#8a3b2e" stroke-width="4"/><text x="512" y="160" font-family="Georgia,serif" font-style="italic" font-size="15" fill="#8a3b2e">Warned in time</text><g transform="translate(396 156) scale(1.25)"><g class="a6h-walk">${heron}</g></g></svg><figcaption>${esc(caption)}</figcaption></figure>`;
}
